    dict(title="03 · Covariance nulle ≠ indépendance", lab="urne", level="Sup", params={}, question="Z est uniforme sur {−1,0,1}. Les variables Z et Z² sont-elles indépendantes ? Leur covariance est-elle nulle ?", answer="E(Z)=E(Z³)=0, donc Cov(Z,Z²)=0. Pourtant P(Z²=0 | Z=0)=1 tandis que P(Z²=0)=1/3 : elles sont dépendantes. L’expérience sur l’urne illustre un autre cas, avec covariance strictement négative."),
    dict(title="04 · Somme de binomiales — ex. 5", lab="fluctuations", level="Sup / spé", params=dict(n=50, p=.3), question="X~B(n,p) et Y~B(m,p) sont indépendantes. Déterminer la loi de X+Y. Que se passe-t-il si les paramètres diffèrent ?", answer="G_{X+Y}=(1−p+pt)ⁿ(1−p+pt)ᵐ=(1−p+pt)^{n+m}. La somme suit B(n+m,p). Pour deux Bernoulli de paramètres p≠q, la variance p(1−p)+q(1−q) diffère de celle de B(2,(p+q)/2) de −(p−q)²/2 ; la somme n’est pas cette binomiale."),
    dict(title="05 · Une espérance astucieuse — ex. 5", lab="fluctuations", level="Sup", params=dict(n=20,p=.3), question="Si X~B(n,p), calculer E[1/(X+1)] sans additionner numériquement tous les termes.", answer="Utiliser 1/(k+1)=∫₀¹tᵏdt dans la somme finie. E[1/(X+1)]=∫₀¹(1−p+pt)ⁿdt=[1−(1−p)^{n+1}]/[(n+1)p] pour p>0. Pour p=0, X=0 et le résultat vaut 1, également limite de la formule."),
    dict(title="06 · Le retour de la marche — TP", lab="fluctuations", level="Sup", params=dict(n=20,p=.5), question="Une marche symétrique de 20 étapes part de 0. Calculer P(S₂₀=0), puis P(S₂₀=4).", answer="S₂₀=2K−20 avec K~B(20,1/2). Les événements correspondent à K=10 et K=12. Ainsi P(S₂₀=0)=C(20,10)/2²⁰≈0,176197 et P(S₂₀=4)=C(20,12)/2²⁰≈0,120134. Une marche de longueur impaire ne peut pas revenir en 0."),
    dict(title="07 · Dimensionner une simulation", lab="fluctuations", level="Sup / spé", params=dict(n=1000,p=.5,epsilon=.05), question="Combien de Bernoulli indépendantes suffisent, par Tchebychev, pour garantir P(|F_N−p|≥0,05)≤0,05 pour tout p ?", answer="Comme p(1−p)≤1/4, la borne est 1/(4Nε²). Il suffit de N≥1/(4×0,05×0,05²)=2000. C’est une condition suffisante conservatrice, non un minimum exact. Le laboratoire montre la borne et la probabilité binomiale pour n≤1000 ; la démonstration donne le dimensionnement au-delà."),
    dict(title="08 · Deux moments — ex. 6", lab="polarisation", level="Priorité · spé", params=dict(c=.35,lambda_= .25,steps=20), question="Montrer que la moyenne est constante et obtenir une expression fermée du second moment.", answer="En conditionnant par Xₙ=x, E(Xₙ₊₁|x)=x et E(Xₙ₊₁²|x)=(1−λ²)x²+λ²x. Donc m₁=c et m₂−c est multiplié par 1−λ² à chaque étape. Comme m₂(0)=c², m₂(n)=c−c(1−c)(1−λ²)ⁿ."),
    dict(title="09 · Tous les moments — ex. 6", lab="polarisation", level="Priorité · spé", params=dict(c=.35,lambda_= .25,steps=100), question="Donner une preuve quantitative de E(Xₙᵏ)→c pour chaque entier k≥1.", answer="Pour k≥2, 0≤x−xᵏ=x(1−x)Σ_{j=0}^{k−2}xʲ≤(k−1)x(1−x) sur [0,1]. Ainsi 0≤c−E(Xₙᵏ)≤(k−1)c(1−c)(1−λ²)ⁿ→0. Le cas k=1 est déjà exact. Il est inutile de résoudre une récurrence différente pour chaque k."),
    dict(title="10 · Quelle convergence ? — ex. 6", lab="polarisation", level="Priorité · spé", params=dict(c=.5,lambda_= .4,steps=100), question="Xₙ converge-t-elle vers c ? Justifier la loi limite et distinguer les modes de convergence.", answer="La masse de [ε,1−ε] tend vers zéro, tandis que la moyenne reste c. Pour f continue, soustraire la corde (1−x)f(0)+xf(1) et utiliser la continuité aux extrémités : E[f(Xₙ)]→(1−c)f(0)+cf(1). C’est Bernoulli(c), pas la constante c. Par exemple V(Xₙ)→c(1−c)>0 ; comme les variables sont bornées, une convergence en probabilité vers c entraînerait une variance tendant vers zéro."),
